package com.orchestrator.api

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.sessions.*
import io.ktor.http.*
import io.ktor.server.plugins.contentnegotiation.*
import io.ktor.serialization.kotlinx.json.*
import kotlinx.serialization.Serializable
import java.util.UUID
import java.security.SecureRandom
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

@Serializable
data class ContainerSpec(val image: String, val replicas: Int, val env: Map<String, String> = emptyMap())

@Serializable
data class UserSession(val userId: String, val csrfToken: String)

data class SessionData(val userId: String, val csrfToken: String, val createdAt: Long)

object SessionStore {
    private val sessions = ConcurrentHashMap<String, SessionData>()
    fun create(userId: String): Pair<String, String> {
        val sessionId = UUID.randomUUID().toString()
        val csrf = generateToken()
        sessions[sessionId] = SessionData(userId, csrf, System.currentTimeMillis())
        return Pair(sessionId, csrf)
    }
    fun get(sessionId: String): SessionData? = sessions[sessionId]
    private fun generateToken(): String {
        val bytes = ByteArray(32)
        SecureRandom().nextBytes(bytes)
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
    }
}

object ContainerManager {
    private val deployments = ConcurrentHashMap<String, ContainerSpec>()
    fun deploy(userId: String, spec: ContainerSpec): String {
        val deployId = UUID.randomUUID().toString()
        deployments[deployId] = spec
        println("[DEPLOY] User=$userId image=${spec.image} replicas=${spec.replicas}")
        return deployId
    }
    fun scale(deployId: String, replicas: Int): Boolean {
        val spec = deployments[deployId] ?: return false
        deployments[deployId] = spec.copy(replicas = replicas)
        println("[SCALE] $deployId -> $replicas replicas")
        return true
    }
    fun delete(deployId: String): Boolean {
        println("[DELETE] $deployId")
        return deployments.remove(deployId) != null
    }
}

fun Application.configureRouting() {
    routing {
        post("/api/auth/login") {
            val params = call.receiveParameters()
            val username = params["username"] ?: return@post call.respond(HttpStatusCode.BadRequest)
            val (sessionId, csrf) = SessionStore.create(username)
            call.response.cookies.append(
                Cookie("SESSION_ID", sessionId, httpOnly = true, secure = true, path = "/",
                    extensions = mapOf("SameSite" to "Lax"))
            )
            call.respond(mapOf("csrf_token" to csrf))
        }

        post("/api/containers/deploy") {
            val session = validateRequest(call) ?: return@post
            val spec = call.receive<ContainerSpec>()
            if (!isValidImage(spec.image)) {
                call.respond(HttpStatusCode.BadRequest, "Invalid image reference")
                return@post
            }
            val deployId = ContainerManager.deploy(session.userId, spec)
            call.respond(mapOf("deploy_id" to deployId))
        }

        post("/api/containers/{id}/scale") {
            val session = validateRequest(call) ?: return@post
            val deployId = call.parameters["id"] ?: return@post call.respond(HttpStatusCode.BadRequest)
            val params = call.receiveParameters()
            val replicas = params["replicas"]?.toIntOrNull() ?: return@post call.respond(HttpStatusCode.BadRequest)
            if (ContainerManager.scale(deployId, replicas)) {
                call.respond(HttpStatusCode.OK)
            } else {
                call.respond(HttpStatusCode.NotFound)
            }
        }

        delete("/api/containers/{id}") {
            val session = validateRequest(call) ?: return@delete
            val deployId = call.parameters["id"] ?: return@delete call.respond(HttpStatusCode.BadRequest)
            if (ContainerManager.delete(deployId)) {
                call.respond(HttpStatusCode.OK)
            } else {
                call.respond(HttpStatusCode.NotFound)
            }
        }

        post("/api/containers/upload-spec") {
            val session = validateUploadRequest(call) ?: return@post
            val spec = call.receive<ContainerSpec>()
            if (!isValidImage(spec.image)) {
                call.respond(HttpStatusCode.BadRequest, "Invalid image reference")
                return@post
            }
            val deployId = ContainerManager.deploy(session.userId, spec)
            call.respond(mapOf("deploy_id" to deployId))
        }
    }
}

suspend fun validateRequest(call: ApplicationCall): SessionData? {
    val sessionId = call.request.cookies["SESSION_ID"]
    if (sessionId == null) {
        call.respond(HttpStatusCode.Unauthorized)
        return null
    }
    val session = SessionStore.get(sessionId)
    if (session == null) {
        call.respond(HttpStatusCode.Unauthorized)
        return null
    }
    val csrfHeader = call.request.header("X-CSRF-Token")
    if (csrfHeader == null || !timingSafeEquals(csrfHeader, session.csrfToken)) {
        call.respond(HttpStatusCode.Forbidden, "CSRF validation failed")
        return null
    }
    return session
}

suspend fun validateUploadRequest(call: ApplicationCall): SessionData? {
    val sessionId = call.request.cookies["SESSION_ID"]
    if (sessionId == null) {
        call.respond(HttpStatusCode.Unauthorized)
        return null
    }
    val session = SessionStore.get(sessionId)
    if (session == null) {
        call.respond(HttpStatusCode.Unauthorized)
        return null
    }
    // Upload endpoints use content-type validation as CSRF mitigation
    // since custom content types cannot be sent cross-origin without preflight
    val contentType = call.request.contentType()
    if (contentType.match(ContentType.Application.Json)) {
        return session
    }
    call.respond(HttpStatusCode.UnsupportedMediaType)
    return null
}

fun timingSafeEquals(a: String, b: String): Boolean {
    val aBytes = a.toByteArray()
    val bBytes = b.toByteArray()
    if (aBytes.size != bBytes.size) return false
    var result = 0
    for (i in aBytes.indices) {
        result = result or (aBytes[i].toInt() xor bBytes[i].toInt())
    }
    return result == 0
}

fun isValidImage(image: String): Boolean {
    val pattern = Regex("^[a-zA-Z0-9][a-zA-Z0-9._/-]{0,255}(:[a-zA-Z0-9._-]{1,128})?$")
    return pattern.matches(image)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        install(ContentNegotiation) { json() }
        configureRouting()
    }.start(wait = true)
}
